147		// ServeMux's plain-text 405: the endpoint's only method is GET.
148		mux.HandleFunc("/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe", func(w http.ResponseWriter, _ *http.Request) {
149			writeError(w, http.StatusBadRequest, "method is not allowed on this path")
150		})
151		// Any other path under the new namespaces is a JSON 404 rather than
152		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
153		// Exact method-patterns above take precedence over these subtree patterns.
154		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
155			writeError(w, http.StatusNotFound, "unknown device/session path")
156		})
