169		})
170		// Non-GET verbs on the poll path: the exact GET pattern above is more
171		// specific, so only other verbs reach this method-less pattern and get a
172		// JSON 400 instead of ServeMux's plain-text 405.
173		mux.HandleFunc("/v1/documents/{documentID}/changes/poll", func(w http.ResponseWriter, _ *http.Request) {
