198		// ServeMux treats any empty path segment (the doubled slash in
199		// /v1/documents//..., /v1/devices//sessions or
200		// /v1/sessions//documents/...) as an unclean path and answers with a 307
201		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
202		// error for an empty identifier, so intercept those paths before the mux
203		// sees them. A trailing slash empties the final id of the device/session
204		// routes and is rejected there for the same reason; the document routes
205		// keep their pre-existing ServeMux behavior.
206		return emptyIDGuard(mux)
207	}
