209	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
210	// JSON error instead of letting ServeMux emit its HTML redirect or a
211	// plain-text 404.
212	//
213	// The document family keeps its original rule (an empty documentID, i.e. the
214	// prefix /v1/documents//); other odd paths there retain their old response so
215	// the pre-existing surface is unchanged. The new device/session families are
216	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
217	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
218	func emptyIDGuard(next http.Handler) http.Handler {
219		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
220			p := r.URL.Path
221	
222			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
223			newFamilySegmentEmpty := false
224			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
225				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
226			}
227	
228			if documentSegmentEmpty || newFamilySegmentEmpty || malformedNewDocumentPath(p) || malformedSubscribePath(p) {
229				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
230				return
231			}
232			next.ServeHTTP(w, r)
233		})
234	}
235	
236	// malformedNewDocumentPath reports whether p targets one of the new
237	// long-poll/replay endpoints but is not that endpoint's exact location: a
238	// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
239	// segment in a position short of the registered shape. ServeMux would answer
240	// those with a 301 redirect or a plain-text 404/405; the new endpoints promise
241	// a JSON error and never a redirect, so every such path is a malformed 400.
242	//
243	// Keywords are matched only past the documentID position, so documents that
244	// happen to be named "poll" or "replay" keep their ordinary merge/snapshot/
245	// changes routes.
246	func malformedNewDocumentPath(p string) bool {
247		rest, ok := strings.CutPrefix(p, "/v1/documents/")
248		if !ok {
249			return false
250		}
251		segs := strings.Split(rest, "/")
252	
253		// Poll endpoint: "poll" must be exactly the third segment, after a
254		// non-empty documentID and "changes".
255		for i, seg := range segs {
256			if seg == "poll" && i > 0 {
257				return !(len(segs) == 3 && segs[0] != "" && segs[1] == "changes")
258			}
259		}
260		// Replay endpoint: "replay" must be exactly the second segment, after a
261		// non-empty documentID.
262		for i, seg := range segs {
263			if seg == "replay" && i > 0 {
264				return !(len(segs) == 2 && segs[0] != "")
265			}
266		}
267		return false
268	}
269	
270	// malformedSubscribePath reports whether p targets the WebSocket subscription
271	// endpoint but is not at its exact location
272	// (/v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe): a
273	// missing "documents"/"changes" segment, an extra segment, or a "subscribe"
274	// segment short of the registered shape. ServeMux would answer those with a
275	// plain-text 404/405; every failure of this endpoint must be a JSON 400
276	// instead. Empty segments are already rejected by the guard itself.
277	func malformedSubscribePath(p string) bool {
278		rest, ok := strings.CutPrefix(p, "/v1/sessions/")
279		if !ok {
280			return false
281		}
282		segs := strings.Split(rest, "/")
283		for _, seg := range segs {
284			if seg == "subscribe" {
285				return !(len(segs) == 5 &&
286					segs[0] != "" &&
287					segs[1] == "documents" &&
288					segs[2] != "" &&
289					segs[3] == "changes")
290			}
291		}
292		return false
293	}
