295	// Handler exposes the HTTP surface over a private in-memory store. Use
296	// NewHandler with a durable store for real deployments.
297	func Handler() http.Handler {
298		s, err := store.Open("")
299		if err != nil {
300			log.Fatalf("open in-memory store: %v", err)
301		}
302		return NewHandler(s)
303	}
304	
305	// decodeJSONBody enforces the strict POST contract shared by every JSON
306	// endpoint: Content-Type must be application/json, the body is capped at
307	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
308	// may follow it. Any violation writes a 400 JSON error and returns false; the
309	// caller returns immediately, so no handler reaches the store with malformed
310	// input and rejected requests write nothing.
311	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
312		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
313		if err != nil || mediaType != "application/json" {
314			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
315			return false
316		}
317	
318		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
319		dec := json.NewDecoder(r.Body)
320		if err := dec.Decode(dst); err != nil {
321			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
322			return false
323		}
324		// Reject trailing data after the JSON value.
325		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
326			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
327			return false
328		}
329		return true
330	}
