332	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
333		var req deviceRequest
334		if !decodeJSONBody(w, r, &req) {
335			return
336		}
337		if req.DeviceID == "" {
338			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
339			return
340		}
341	
342		created, err := s.RegisterDevice(req.DeviceID)
343		if err != nil {
344			writeError(w, http.StatusInternalServerError, "failed to register device")
345			return
346		}
347	
348		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
349	}
