396	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
397		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
398	
399		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
400		if err != nil || mediaType != "application/json" {
401			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
402			return
403		}
404	
405		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
406		var req postRequest
407		dec := json.NewDecoder(r.Body)
408		if err := dec.Decode(&req); err != nil {
409			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
410			return
411		}
412		// Reject trailing data after the JSON object.
413		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
414			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
415			return
416		}
417	
418		if req.DeviceID == "" {
419			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
420			return
421		}
422		if len(req.Changes) == 0 {
423			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
424			return
425		}
426	
427		changes := make([]store.Change, len(req.Changes))
428		seen := make(map[string]struct{}, len(req.Changes))
429		for i, c := range req.Changes {
430			if c.ID == "" {
431				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
432				return
433			}
434			if len(c.Payload) == 0 {
435				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
436				return
437			}
438			if _, dup := seen[c.ID]; dup {
439				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
440				return
441			}
442			seen[c.ID] = struct{}{}
443			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
444		}
445	
446		results, err := s.PostChanges(documentID, changes)
447		if err != nil {
448			var conflict *store.ErrConflict
449			if errors.As(err, &conflict) {
450				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
451				return
452			}
453			writeError(w, http.StatusInternalServerError, "failed to commit changes")
454			return
455		}
456	
457		writeJSON(w, http.StatusOK, map[string]any{"results": results})
458	}
459	
460	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
461		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
462	
463		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
464		if err != nil || mediaType != "application/json" {
465			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
466			return
467		}
468	
469		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
470		var req mergeRequest
471		dec := json.NewDecoder(r.Body)
472		if err := dec.Decode(&req); err != nil {
473			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
474			return
475		}
476		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
477			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
478			return
479		}
480	
481		if req.DeviceID == "" {
482			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
483			return
484		}
485		// baseCursor must be present and a non-negative integer (no fractions,
486		// strings, booleans or null).
487		if len(req.BaseCursor) == 0 {
488			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
489			return
490		}
491		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
492		if !ok {
493			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
494			return
495		}
496		if req.Change == nil {
497			writeError(w, http.StatusBadRequest, "change must be an object")
498			return
499		}
500		if req.Change.ID == "" {
501			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
502			return
503		}
504		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
505			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
506			return
507		}
508	
509		result, err := s.MergeChange(documentID, baseCursor, store.Change{
510			ID:       req.Change.ID,
511			DeviceID: req.DeviceID,
512			Payload:  req.Change.Payload,
513		})
514		if err != nil {
515			var conflict *store.ErrConflict
516			switch {
517			case errors.Is(err, store.ErrStaleCursor):
518				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
519				return
520			case errors.As(err, &conflict):
521				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
522				return
523			default:
524				writeError(w, http.StatusInternalServerError, "failed to merge change")
525				return
526			}
527		}
528	
529		writeJSON(w, http.StatusOK, result)
530	}
