532	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
533		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
534	
535		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
536		if err != nil || mediaType != "application/json" {
537			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
538			return
539		}
540	
541		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
542		var req snapshotPostRequest
543		dec := json.NewDecoder(r.Body)
544		if err := dec.Decode(&req); err != nil {
545			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
546			return
547		}
548		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
549			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
550			return
551		}
552	
553		cursor, ok := parseNonNegativeInt(req.Cursor)
554		if !ok {
555			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
556			return
557		}
558		if len(req.State) == 0 {
559			writeError(w, http.StatusBadRequest, "state is required")
560			return
561		}
562	
563		created, err := s.PutSnapshot(documentID, cursor, req.State)
564		if err != nil {
565			var conflict *store.ErrSnapshotConflict
566			switch {
567			case errors.Is(err, store.ErrSnapshotBase):
568				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
569				return
570			case errors.As(err, &conflict):
571				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
572				return
573			default:
574				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
575				return
576			}
577		}
578	
579		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
580	}
581	
582	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
583		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
584	
585		cursor, ok := parseCursorPath(r.PathValue("cursor"))
586		if !ok {
587			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
588			return
589		}
590	
591		state, err := s.GetSnapshot(documentID, cursor)
592		if err != nil {
593			if errors.Is(err, store.ErrSnapshotNotFound) {
594				writeError(w, http.StatusNotFound, "snapshot not found")
595				return
596			}
597			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
598			return
599		}
600	
601		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
602	}
603	
604	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
605		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
606	
607		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
608		if err != nil || mediaType != "application/json" {
609			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
610			return
611		}
612	
613		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
614		var req restoreRequest
615		dec := json.NewDecoder(r.Body)
616		if err := dec.Decode(&req); err != nil {
617			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
618			return
619		}
620		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
621			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
622			return
623		}
624	
625		if req.DeviceID == "" {
626			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
627			return
628		}
629		if req.ChangeID == "" {
630			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
631			return
632		}
633		// snapshotCursor must be present and a positive integer (no fractions,
634		// strings, booleans, null or zero).
635		if len(req.SnapshotCursor) == 0 {
636			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
637			return
638		}
639		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
640		if !ok {
641			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
642			return
643		}
644	
645		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
646		if err != nil {
647			var conflict *store.ErrRestoreConflict
648			switch {
649			case errors.Is(err, store.ErrSnapshotNotFound):
650				writeError(w, http.StatusNotFound, "snapshot not found")
651				return
652			case errors.As(err, &conflict):
653				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
654				return
655			default:
656				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
657				return
658			}
659		}
660	
661		writeJSON(w, http.StatusOK, result)
662	}
663	
664	// handleSetPermission grants or revokes a registered device's access to one
665	// document. Devices start authorized, so the first revoke is the first write;
666	// repeating the current state is idempotent (changed=false). A rejected
667	// request (bad content type, malformed JSON, trailing content, empty or
668	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
669	// unregistered device is a 404 JSON error.
670	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
671		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
672	
673		var req permissionRequest
674		if !decodeJSONBody(w, r, &req) {
675			return
676		}
677		if req.DeviceID == "" {
678			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
679			return
680		}
681		var authorized bool
682		switch req.Action {
683		case "grant":
684			authorized = true
685		case "revoke":
686			authorized = false
687		default:
688			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
689			return
690		}
691	
692		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
693		if err != nil {
694			if errors.Is(err, store.ErrDeviceNotFound) {
695				writeError(w, http.StatusNotFound, "device not found")
696				return
697			}
698			writeError(w, http.StatusInternalServerError, "failed to update permission")
699			return
700		}
701	
702		writeJSON(w, http.StatusOK, map[string]any{
703			"deviceId":   req.DeviceID,
704			"authorized": authorized,
705			"changed":    changed,
706		})
707	}
708	
709	// parseCursorPath reports whether raw is a decimal non-negative integer and
710	// returns its value. Signs, fractions and other adornments are rejected.
711	func parseCursorPath(raw string) (int64, bool) {
712		if raw == "" {
713			return 0, false
714		}
715		for _, c := range raw {
716			if c < '0' || c > '9' {
717				return 0, false
718			}
719		}
720		n, err := strconv.ParseInt(raw, 10, 64)
721		if err != nil {
722			return 0, false
723		}
724		return n, true
725	}
726	
727	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
728	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
729		var n int64
730		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
731			return 0, false
732		}
733		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
734		// require the literal to contain no fraction or exponent.
735		trimmed := strings.TrimSpace(string(raw))
736		if trimmed == "" || trimmed[0] == '-' {
737			return 0, false
738		}
739		for _, c := range trimmed {
740			if c < '0' || c > '9' {
741				return 0, false
742			}
743		}
744		return n, true
745	}
746	
747	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
748	// strings, booleans, null and negative numbers are rejected.
749	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
750		n, ok := parseNonNegativeInt(raw)
751		if !ok || n < 1 {
752			return 0, false
753		}
754		return n, true
755	}
756	
757	// isJSONObject reports whether raw decodes to a JSON object (not null, an
758	// array or a scalar).
759	func isJSONObject(raw json.RawMessage) bool {
760		var m map[string]json.RawMessage
761		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
762			return false
763		}
764		return true
765	}
766	
767	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
768		documentID := r.PathValue("documentID")
769	
770		after, limit, ok := parseChangesQuery(w, r)
771		if !ok {
772			return
773		}
774	
775		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
776		if err != nil {
777			writeError(w, http.StatusInternalServerError, "failed to list changes")
778			return
779		}
780	
781		writeChangesPage(w, changes, nextCursor)
782	}
783	
784	// handleSessionChanges is the session-scoped view of the existing change log:
785	// both path identifiers must be non-empty (the empty-segment guard rejects
786	// those before routing) and the session must currently exist, after which the
787	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
788	// the session's device has been revoked permission for the document, which is
789	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
790	// read; the change log itself is untouched.
791	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
792		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
793		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
794	
795		// Malformed query parameters are a request-shape error (400) checked
796		// before the resource lookup (404), matching the snapshot GET ordering.
797		after, limit, ok := parseChangesQuery(w, r)
798		if !ok {
799			return
800		}
801	
802		deviceID, err := s.SessionDevice(sessionID)
803		if err != nil {
804			if errors.Is(err, store.ErrSessionNotFound) {
805				writeError(w, http.StatusNotFound, "session not found")
806				return
807			}
808			writeError(w, http.StatusInternalServerError, "failed to look up session")
809			return
810		}
811	
812		authorized, err := s.DocumentAuthorized(documentID, deviceID)
813		if err != nil {
814			writeError(w, http.StatusInternalServerError, "failed to look up permission")
815			return
816		}
817		if !authorized {
818			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
819			return
820		}
821	
822		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
823		if err != nil {
824			writeError(w, http.StatusInternalServerError, "failed to list changes")
825			return
826		}
827	
828		writeChangesPage(w, changes, nextCursor)
829	}
830	
831	// parseChangesQuery parses the shared after/limit pagination parameters,
832	// writing the documented 400 on an illegal value. It is shared by the
833	// document-scoped and session-scoped change listings so their query semantics
834	// cannot drift apart.
835	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
836		q := r.URL.Query()
837	
838		after = 0
839		if raw := q.Get("after"); raw != "" {
840			v, err := strconv.ParseInt(raw, 10, 64)
841			if err != nil || v < 0 {
842				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
843				return 0, 0, false
844			}
845			after = v
846		}
847	
848		limit = defaultListLimit
849		if raw := q.Get("limit"); raw != "" {
850			v, err := strconv.ParseInt(raw, 10, 64)
851			if err != nil || v < 1 || v > maxListLimit {
852				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
853				return 0, 0, false
854			}
855			limit = v
856		}
857	
858		return after, limit, true
859	}
860	
861	// writeChangesPage renders a change listing page in the shared response shape.
862	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
863		writeJSON(w, http.StatusOK, map[string]any{
864			"changes":    changes,
865			"nextCursor": nextCursor,
866		})
867	}
868	
869	func writeJSON(w http.ResponseWriter, status int, v any) {
870		w.Header().Set("Content-Type", "application/json")
871		w.WriteHeader(status)
872		_ = json.NewEncoder(w).Encode(v)
873	}
874	
875	func writeError(w http.ResponseWriter, status int, message string) {
876		writeJSON(w, status, map[string]string{"error": message})
877	}
878	
879	// handlePollChanges is the long-polling entry over the change log.
880	//
881	// Query params share the existing change-read constraints: after is a
882	// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
883	// is 0..30000 (default 0). Rows already past after return immediately; a known
884	// document caught up to after parks until the first new commit or the wait
885	// deadline; an unknown document returns an empty page with cursor 0 at once.
886	// The response shape is the ordinary page plus a timedOut flag; a deadline
887	// expiry echoes the caller's cursor and never advances it. A client
888	// disconnect simply stops the wait and writes nothing.
889	func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
890		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
891	
892		after, limit, ok := parseChangesQuery(w, r)
893		if !ok {
894			return
895		}
896		q := r.URL.Query()
897		var waitMs int64
898		if raw := q.Get("waitMs"); raw != "" {
899			v, err := strconv.ParseInt(raw, 10, 64)
900			if err != nil || v < 0 || v > maxPollWaitMillis {
901				writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
902				return
903			}
904			waitMs = v
905		}
906	
907		changes, nextCursor, timedOut, err := s.WaitForChanges(
908			r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
909		)
910		switch {
911		case errors.Is(err, store.ErrStoreClosing):
912			writeError(w, http.StatusServiceUnavailable, "service is shutting down")
913			return
914		case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
915			// The client went away (or, with waitMs bounded, its deadline lapsed
916			// at the transport): nothing more to write and nothing was stored.
917			return
918		case err != nil:
919			writeError(w, http.StatusInternalServerError, "failed to poll changes")
920			return
921		}
922	
923		writeJSON(w, http.StatusOK, map[string]any{
924			"changes":    changes,
925			"nextCursor": nextCursor,
926			"timedOut":   timedOut,
927		})
928	}
929	
930	// handleReplay retries an offline batch against the existing change log. The
931	// request and per-element semantics mirror POST .../changes — strict
932	// application/json body, non-empty ids, no in-batch duplicates, idempotent only
933	// when deviceId and decoded payload match, otherwise 409 reporting the
934	// conflicting id — with the registration/permission layer enforced first:
935	// 404 for an unregistered device and 403 for a revoked one, neither exposing
936	// change content. The whole batch commits in one serialized transaction that
937	// shares the document's contiguous cursor space with ordinary commits.
938	func handleReplay(s *store.Store, w http.ResponseWriter, r *http.Request) {
939		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
940	
941		var req replayRequest
942		if !decodeJSONBody(w, r, &req) {
943			return
944		}
945		if req.DeviceID == "" {
946			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
947			return
948		}
949		if req.Operations == nil {
950			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
951			return
952		}
953		if len(req.Operations) == 0 {
954			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
955			return
956		}
957	
958		changes := make([]store.Change, len(req.Operations))
959		seen := make(map[string]struct{}, len(req.Operations))
960		for i, op := range req.Operations {
961			if op.ID == "" {
962				writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
963				return
964			}
965			if len(op.Payload) == 0 {
966				writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
967				return
968			}
969			if _, dup := seen[op.ID]; dup {
970				writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
971				return
972			}
973			seen[op.ID] = struct{}{}
974			changes[i] = store.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
975		}
976	
977		results, err := s.ReplayChanges(documentID, changes)
978		if err != nil {
979			var conflict *store.ErrConflict
980			switch {
981			case errors.Is(err, store.ErrDeviceNotFound):
982				writeError(w, http.StatusNotFound, "device not found")
983			case errors.Is(err, store.ErrPermissionDenied):
984				writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
985			case errors.As(err, &conflict):
986				writeJSON(w, http.StatusConflict, map[string]string{
987					"error":      "operation id already exists with different deviceId or payload",
988					"conflictId": conflict.ID,
989				})
990			default:
991				writeError(w, http.StatusInternalServerError, "failed to replay operations")
992			}
993			return
994		}
995	
996		writeJSON(w, http.StatusOK, map[string]any{"results": results})
997	}
998

