1	package server
2	
3	import (
4		"bufio"
5		"crypto/rand"
6		"crypto/sha1"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/json"
10		"fmt"
11		"io"
12		"net"
13		"net/http"
14		"net/http/httptest"
15		"net/url"
16		"path/filepath"
17		"strings"
18		"testing"
19		"time"
20	
21		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
22	)
23	
24	// wsClient is a minimal raw RFC 6455 client used to drive the subscription
25	// endpoint over a real TCP connection (HTTP hijacking does not work with
26	// httptest.ResponseRecorder).
27	type wsClient struct {
28		t    *testing.T
29		conn net.Conn
30		br   *bufio.Reader
31	}
32	
33	func newWSKey() string {
34		b := make([]byte, 16)
35		_, _ = rand.Read(b)
36		return base64.StdEncoding.EncodeToString(b)
37	}
38	
39	// dialWS performs the opening handshake against an httptest.Server URL. A
40	// non-101 response is returned as (nil, response) so tests can assert the
41	// 400/403/404 JSON failures.
42	func dialWS(t *testing.T, serverURL string) (*wsClient, *http.Response) {
43		t.Helper()
44		u, err := url.Parse(serverURL)
45		if err != nil {
46			t.Fatal(err)
47		}
48		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
49		if err != nil {
50			t.Fatalf("dial: %v", err)
51		}
52		key := newWSKey()
53		req := fmt.Sprintf(
54			"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"+
55				"Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n",
56			u.RequestURI(), u.Host, key)
57		if _, err := io.WriteString(conn, req); err != nil {
58			_ = conn.Close()
59			t.Fatalf("write handshake: %v", err)
60		}
61		br := bufio.NewReader(conn)
62		resp, err := http.ReadResponse(br, nil)
63		if err != nil {
64			_ = conn.Close()
65			t.Fatalf("read handshake: %v", err)
66		}
67		if resp.StatusCode != http.StatusSwitchingProtocols {
68			_ = conn.Close()
69			return nil, resp
70		}
71		sum := sha1.Sum([]byte(key + wsGUID))
72		if got := resp.Header.Get("Sec-WebSocket-Accept"); got != base64.StdEncoding.EncodeToString(sum[:]) {
73			_ = conn.Close()
74			t.Fatalf("accept = %q, want the RFC 6455 digest", got)
75		}
76		return &wsClient{t: t, conn: conn, br: br}, resp
77	}
78	
79	// dialWSRaw sends a caller-built handshake request, for negative tests that
80	// omit or corrupt a header.
81	func dialWSRaw(t *testing.T, serverURL, requestTarget string, headers ...string) (*http.Response, net.Conn) {
82		t.Helper()
83		u, err := url.Parse(serverURL)
84		if err != nil {
85			t.Fatal(err)
86		}
87		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
88		if err != nil {
89			t.Fatalf("dial: %v", err)
90		}
91		var b strings.Builder
92		b.WriteString("GET " + requestTarget + " HTTP/1.1\r\n")
93		b.WriteString("Host: " + u.Host + "\r\n")
94		for _, h := range headers {
95			b.WriteString(h + "\r\n")
96		}
97		b.WriteString("\r\n")
98		if _, err := io.WriteString(conn, b.String()); err != nil {
99			_ = conn.Close()
100			t.Fatalf("write handshake: %v", err)
101		}
102		br := bufio.NewReader(conn)
103		resp, err := http.ReadResponse(br, nil)
104		if err != nil {
105			_ = conn.Close()
106			t.Fatalf("read handshake: %v", err)
107		}
108		return resp, conn
109	}
110	
111	// readFrame reads one server (unmasked) frame.
112	func (c *wsClient) readFrame() (fin bool, opcode byte, payload []byte) {
113		c.t.Helper()
114		header := make([]byte, 2)
115		if _, err := io.ReadFull(c.br, header); err != nil {
116			c.t.Fatalf("read frame header: %v", err)
117		}
118		fin = header[0]&0x80 != 0
119		opcode = header[0] & 0x0F
120		length := int64(header[1] & 0x7F)
121		switch length {
122		case 126:
123			var ext [2]byte
124			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
125				c.t.Fatalf("read ext len: %v", err)
126			}
127			length = int64(binary.BigEndian.Uint16(ext[:]))
128		case 127:
129			var ext [8]byte
130			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
131				c.t.Fatalf("read ext len: %v", err)
132			}
133			length = int64(binary.BigEndian.Uint64(ext[:]))
134		}
135		payload = make([]byte, length)
136		if length > 0 {
137			if _, err := io.ReadFull(c.br, payload); err != nil {
138				c.t.Fatalf("read payload: %v", err)
139			}
140		}
141		return fin, opcode, payload
142	}
143	
144	func closeCode(payload []byte) int {
145		if len(payload) < 2 {
146			return -1
147		}
148		return int(binary.BigEndian.Uint16(payload[:2]))
149	}
150	
151	// readFrameMaybe is the non-fatal variant used by negative assertions: with a
152	// read deadline already set it reports ok=false on a timeout/EOF instead of
153	// failing the test.
154	func (c *wsClient) readFrameMaybe() (fin bool, opcode byte, payload []byte, ok bool) {
155		header := make([]byte, 2)
156		if _, err := io.ReadFull(c.br, header); err != nil {
157			return false, 0, nil, false
158		}
159		fin = header[0]&0x80 != 0
160		opcode = header[0] & 0x0F
161		length := int64(header[1] & 0x7F)
162		switch length {
163		case 126:
164			var ext [2]byte
165			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
166				return false, 0, nil, false
167			}
168			length = int64(binary.BigEndian.Uint16(ext[:]))
169		case 127:
170			var ext [8]byte
171			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
172				return false, 0, nil, false
173			}
174			length = int64(binary.BigEndian.Uint64(ext[:]))
175		}
176		payload = make([]byte, length)
177		if length > 0 {
178			if _, err := io.ReadFull(c.br, payload); err != nil {
179				return false, 0, nil, false
180			}
181		}
182		return fin, opcode, payload, true
183	}
184	
185	// readChange reads the next complete text message and decodes one change row.
186	// The server only ever sends whole (FIN) text frames; pongs are skipped.
187	func (c *wsClient) readChange() store.ListedChange {
188		c.t.Helper()
189		for {
190			fin, opcode, payload := c.readFrame()
191			switch opcode {
192			case wsOpcodeText:
193				if !fin {
194					c.t.Fatal("server sent a fragmented text frame")
195				}
196				var change store.ListedChange
197				if err := json.Unmarshal(payload, &change); err != nil {
198					c.t.Fatalf("text frame is not a change row: %s (%v)", payload, err)
199				}
200				return change
201			case wsOpcodePong:
202				continue
203			case wsOpcodeClose:
204				c.t.Fatalf("unexpected close frame while reading change: code=%d", closeCode(payload))
205			default:
206				c.t.Fatalf("unexpected opcode %d while reading change", opcode)
207			}
208		}
209	}
210	
211	// readCloseCode reads frames until the close frame and returns its code.
212	func (c *wsClient) readCloseCode() int {
213		c.t.Helper()
214		for {
215			_, opcode, payload := c.readFrame()
216			if opcode == wsOpcodeClose {
217				return closeCode(payload)
218			}
219		}
220	}
221	
222	// sendMasked writes one masked client frame.
223	func (c *wsClient) sendMasked(opcode byte, payload []byte) {
224		c.t.Helper()
225		mask := make([]byte, 4)
226		_, _ = rand.Read(mask)
227		masked := append([]byte(nil), payload...)
228		for i := range masked {
229			masked[i] ^= mask[i%4]
230		}
231		var header []byte
232		b0 := byte(0x80) | opcode
233		switch {
234		case len(payload) <= 125:
235			header = append(header, b0, 0x80|byte(len(payload)))
236		case len(payload) <= 65535:
237			header = append(header, b0, 0x80|126)
238			ext := make([]byte, 2)
239			binary.BigEndian.PutUint16(ext, uint16(len(payload)))
240			header = append(header, ext...)
241		default:
242			header = append(header, b0, 0x80|127)
243			ext := make([]byte, 8)
244			binary.BigEndian.PutUint64(ext, uint64(len(payload)))
245			header = append(header, ext...)
246		}
247		header = append(header, mask...)
248		if _, err := c.conn.Write(header); err != nil {
249			c.t.Fatalf("write frame header: %v", err)
250		}
251		if len(masked) > 0 {
252			if _, err := c.conn.Write(masked); err != nil {
253				c.t.Fatalf("write frame payload: %v", err)
254			}
255		}
256	}
257	
258	func (c *wsClient) sendText(payload string) { c.sendMasked(wsOpcodeText, []byte(payload)) }
259	func (c *wsClient) sendPing()               { c.sendMasked(wsOpcodePing, nil) }
260	
261	func (c *wsClient) setReadDeadline(d time.Duration) {
262		_ = c.conn.SetReadDeadline(time.Now().Add(d))
263	}
264	func (c *wsClient) clearReadDeadline() { _ = c.conn.SetReadDeadline(time.Time{}) }
265	
266	func (c *wsClient) sendClose(code int) {
267		payload := make([]byte, 2)
268		binary.BigEndian.PutUint16(payload, uint16(code))
269		c.sendMasked(wsOpcodeClose, payload)
270	}
271	
272	func (c *wsClient) close() { _ = c.conn.Close() }
273	
274	// --- fixtures ---------------------------------------------------------------
275	
276	func newWSTestServer(t *testing.T) (*httptest.Server, *store.Store) {
277		t.Helper()
278		st, err := store.Open(filepath.Join(t.TempDir(), "ws.db"))
279		if err != nil {
280			t.Fatal(err)
281		}
282		srv := httptest.NewServer(NewHandler(st))
283		t.Cleanup(srv.Close)
284		t.Cleanup(func() { _ = st.Close() })
285		return srv, st
286	}
287	
288	// setupSession registers a device owning a session and seeds the document with
289	// changes seed-1..seed-N, each carrying {"n":i}, via the public HTTP surface.
290	func setupSession(t *testing.T, srv *httptest.Server, device, session, doc string, seed int) {
291		t.Helper()
292		httpPost := func(path string, body any) {
293			raw, _ := json.Marshal(body)
294			resp, err := srv.Client().Post(srv.URL+path, "application/json", strings.NewReader(string(raw)))
295			if err != nil {
296				t.Fatalf("POST %s: %v", path, err)
297			}
298			defer resp.Body.Close()
299			if resp.StatusCode != http.StatusOK {
300				data, _ := io.ReadAll(resp.Body)
301				t.Fatalf("POST %s = %d %s", path, resp.StatusCode, data)
302			}
303		}
304		httpPost("/v1/devices", map[string]any{"deviceId": device})
305		httpPost("/v1/devices/"+device+"/sessions", map[string]any{"sessionId": session})
306		for i := 0; i < seed; i++ {
307			httpPost("/v1/documents/"+doc+"/changes", map[string]any{
308				"deviceId": device,
309				"changes": []any{
310					map[string]any{"id": fmt.Sprintf("seed-%d", i+1), "payload": map[string]any{"n": i + 1}},
311				},
312			})
313		}
314	}
315	
316	func subscribeURL(srv *httptest.Server, session, doc, cursor string) string {
317		return srv.URL + "/v1/sessions/" + session + "/documents/" + doc + "/changes/subscribe?cursor=" + cursor
318	}
