func TestCRDTTypeFixationAndConcurrentDeclaration(t *testing.T) {
	st, err := newDurableStore(t)
	if err != nil {
		t.Fatal(err)
	}
	srv := newHTTPServer(t, st)
	mustStatus(t, srv, http.MethodPost, "/v1/devices", `{"deviceId":"dev-1"}`)
	mustStatus(t, srv, http.MethodPost, "/v1/devices", `{"deviceId":"dev-2"}`)

	// Fire one counter and one gset first-batch concurrently; exactly one wins.
	var wg sync.WaitGroup
	statuses := make(chan int, 2)
	start := make(chan struct{})
	go func() {
		defer wg.Done()
		wg.Add(1)
		<-start
		statuses <- postStatus(srv, "/v1/documents/race/crdt/ops",
			`{"deviceId":"dev-1","type":"counter","ops":[{"id":"c1","value":1}]}`)
	}()
	go func() {
		defer wg.Done()
		wg.Add(1)
		<-start
		statuses <- postStatus(srv, "/v1/documents/race/crdt/ops",
			`{"deviceId":"dev-2","type":"gset","ops":[{"id":"g1","elements":["x"]}]}`)
	}()
	close(start)
	wg.Wait()
	close(statuses)
	var ok, conflict int
	for code := range statuses {
		switch code {
		case http.StatusOK:
			ok++
		case http.StatusConflict:
			conflict++
		default:
			t.Fatalf("unexpected status %d", code)
		}
	}
	if ok != 1 || conflict != 1 {
		t.Fatalf("ok=%d conflict=%d, want exactly one of each", ok, conflict)
	}

	// The type is now fixed: the losing type keeps getting 409.
	losing := "counter"
	winning := "gset"
	if postStatus(srv, "/v1/documents/race/crdt/ops",
		`{"deviceId":"dev-2","type":"gset","ops":[{"id":"g1","elements":["x"]}]}`) == http.StatusConflict {
		// g1 was the loser above; counter won instead.
		losing, winning = "gset", "counter"
	}
	if code := postStatus(srv, "/v1/documents/race/crdt/ops",
		fmt.Sprintf(`{"deviceId":"dev-1","type":%q,"ops":[{"id":"later","value":2}]}`, losing)); code != http.StatusConflict {
		t.Fatalf("losing type later = %d, want 409", code)
	}
	resp := getJSON(srv, "/v1/documents/race/crdt/state")
	if resp["type"] != winning {
		t.Fatalf("fixed type = %v, want %q", resp["type"], winning)
	}
}

func TestCRDTCounterRegressionIs409(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")

	w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-1",
		map[string]any{"id": "a1", "value": 5}))
