	}
	w, _ = postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-1",
		map[string]any{"id": "a2", "value": 4}))
	if w.Code != http.StatusConflict {
		t.Fatalf("regression status = %d, want 409", w.Code)
	}
	// State is unchanged.
	w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/crdt/state")
	if body["value"].(float64) != 5 {
		t.Fatalf("value after regression = %v, want 5", body["value"])
	}
}

func TestCRDTGSetUnionSortedAndIdempotent(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")

	post := func(device string, id string, elements []string) *response {
		w, body := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtGSetBody(device,
			map[string]any{"id": id, "elements": elements}))
		return &response{w, body}
	}
	if r := post("dev-1", "g1", []string{"banana", "apple"}); r.w.Code != http.StatusOK {
		t.Fatal(r.w.Body.String())
	}
	if r := post("dev-2", "g2", []string{"cherry", "apple"}); r.w.Code != http.StatusOK {
		t.Fatal(r.w.Body.String())
	}
	// Same id, identical content: idempotent created=false.
	r := post("dev-1", "g1", []string{"apple", "banana"})
	if r.w.Code != http.StatusOK {
		t.Fatal(r.w.Body.String())
	}
	created := r.body["results"].([]any)[0].(map[string]any)["created"].(bool)
	if created {
		t.Fatal("identical repeat must be created=false")
	}
	// Same id, different elements: 409 and state unchanged.
	if r := post("dev-1", "g1", []string{"apple", "different"}); r.w.Code != http.StatusConflict {
		t.Fatalf("conflicting repeat = %d, want 409", r.w.Code)
	}
	// Same id from a different device: 409.
	if r := post("dev-2", "g1", []string{"banana", "apple"}); r.w.Code != http.StatusConflict {
		t.Fatalf("cross-device repeat = %d, want 409", r.w.Code)
	}

	w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/crdt/state")
	if w.Code != http.StatusOK || body["type"] != "gset" {
		t.Fatalf("%d %s", w.Code, w.Body.String())
	}
	got := body["value"].([]any)
	want := []string{"apple", "banana", "cherry"}
	if len(got) != len(want) {
		t.Fatalf("elements = %v, want %v", got, want)
	}
	for i := range want {
		if got[i].(string) != want[i] {
			t.Fatalf("elements = %v, want sorted %v", got, want)
		}
	}
}

