func TestCRDTTypeFixationAndConcurrentDeclaration(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")

	// Fire one counter and one gset first-batch concurrently; exactly one wins.
	var wg sync.WaitGroup
	statuses := make(chan int, 2)
	start := make(chan struct{})
	submit := func(device, typ, id, content string) {
		defer wg.Done()
		<-start
		w, _ := postJSON(t, h, "/v1/documents/race/crdt/ops",
			fmt.Sprintf(`{"deviceId":%q,"type":%q,"ops":[%s]}`, device, typ, content))
		statuses <- w.Code
	}
	wg.Add(2)
	go submit("dev-1", "counter", "c1", `{"id":"c1","value":1}`)
	go submit("dev-2", "gset", "g1", `{"id":"g1","elements":["x"]}`)
	close(start)
	wg.Wait()
	close(statuses)
	var ok, conflict int
	for code := range statuses {
		switch code {
		case http.StatusOK:
			ok++
		case http.StatusConflict:
			conflict++
		default:
			t.Fatalf("unexpected status %d", code)
		}
	}
	if ok != 1 || conflict != 1 {
		t.Fatalf("ok=%d conflict=%d, want exactly one of each", ok, conflict)
	}

	// Exactly one type is now readable and fixed; the other keeps getting 409.
	w, body := doRequest(t, h, http.MethodGet, "/v1/documents/race/crdt/state")
	if w.Code != http.StatusOK {
		t.Fatalf("state = %d", w.Code)
	}
	fixed := body["type"].(string)
	losing := "counter"
	if fixed == "counter" {
		losing = "gset"
	}
	losingBody := crdtCounterBody("dev-1", map[string]any{"id": "later", "value": 2})
	if losing == "gset" {
		losingBody = crdtGSetBody("dev-1", map[string]any{"id": "later", "elements": ["y"]})
	}
	w, _ = postJSON(t, h, "/v1/documents/race/crdt/ops", losingBody)
	if w.Code != http.StatusConflict {
		t.Fatalf("losing type %s later = %d, want 409", losing, w.Code)
	}
}

